  ('social-jo', '사회', '조안나T', '사회(조안나T)', '조안나T', '인권 보장과 헌법: 기본권·기본권 제한·권력 분립·헌법재판소.', 4);
insert into public.cards (id, deck_id, kind, topic, badge, question, passage, answer, wrong, criteria, explanation, source_label, source_page, source_slide, source_url, sort) values
  ('social-jo-001', 'social-jo', 'choice', '인권과 헌법', null, '국가의 최고법인 헌법은 인권을 국민의 X(으)로 명시해 보장한다. X는?', null, '기본권', array['자연권', '공권력', '행정권'], '{}'::text[], '헌법은 국가의 최고법으로, 인권을 국민의 기본권으로 명시하여 헌법에 보장한다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 0),
  ('social-jo-002', 'social-jo', 'choice', '인권과 헌법', null, '헌법이 추구하는 궁극의 가치이자 모든 기본권의 근거는?', null, '인간의 존엄과 가치', array['국가 안전 보장', '질서 유지', '공공복리'], '{}'::text[], '인간으로서의 존엄과 가치는 헌법이 추구하는 궁극의 가치이며, 모든 기본권의 근거이자 국가 권력 행사의 기준이다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 1),
  ('social-jo-003', 'social-jo', 'choice', '인권과 헌법', null, '인간으로서의 존엄과 가치에 대한 설명으로 옳지 않은 것은?', null, '공익 위해 수단화 가능', array['인간이라서 존중받음', '인격 훼손은 금지', '국가 권력 행사의 기준'], '{}'::text[], '인간은 인간이라는 이유만으로 존중받아야 하므로, 다른 목적을 위한 수단으로 이용하거나 인격을 훼손해서는 안 된다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 2),
  ('social-jo-004', 'social-jo', 'choice', '인권과 헌법', null, '모든 기본권의 근거 A, 국가의 간섭을 받지 않을 권리 B. A–B는?', null, '존엄과 가치–자유권', array['존엄과 가치–사회권', '평등권–자유권', '자유권–청구권'], '{}'::text[], '인간으로서의 존엄과 가치는 모든 기본권의 근거이고, 국가 권력의 간섭을 받지 않고 자유롭게 생활할 권리는 자유권이다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 3),
  ('social-jo-005', 'social-jo', 'choice', '기본권의 종류', null, '국가 권력의 간섭을 받지 않고 자유롭게 생활할 수 있는 권리는?', null, '자유권', array['사회권', '청구권', '참정권'], '{}'::text[], '자유권은 국가 권력의 간섭을 받지 않고 자유롭게 생활할 수 있는 권리로, 국가의 개입을 막는 방어적·소극적 권리다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 4),
  ('social-jo-006', 'social-jo', 'choice', '기본권의 종류', null, '자유권의 성격에 대한 설명으로 옳지 않은 것은?', null, '국가 개입이 전제됨', array['포괄적 권리', '소극적 권리', '국가에 대한 방어권'], '{}'::text[], '자유권은 헌법에 구체적으로 열거되지 않은 자유도 보장되는 포괄적 권리이며, 국가의 개입을 막는 소극적 권리다. 국가의 개입이 전제되는 것은 사회권·청구권이다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 5),
  ('social-jo-007', 'social-jo', 'choice', '기본권의 종류', null, '신체의 자유, 종교의 자유, 직업 선택의 자유가 속하는 기본권은?', null, '자유권', array['평등권', '사회권', '참정권'], '{}'::text[], '신체의 자유, 종교의 자유, 언론·출판·집회·결사의 자유, 직업 선택의 자유 등은 자유권의 내용이다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 6),
  ('social-jo-008', 'social-jo', 'choice', '기본권의 종류', null, '성별·종교·사회적 신분으로 차별받지 않고 동등하게 대우받을 권리는?', null, '평등권', array['자유권', '청구권', '사회권'], '{}'::text[], '평등권은 모든 국민이 성별, 종교, 사회적 신분 등에 의해 차별받지 않고 동등하게 대우받을 권리다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 7),
  ('social-jo-009', 'social-jo', 'choice', '기본권의 종류', null, '평등권에 대한 설명으로 옳은 것은?', null, '합당한 근거 없는 차별 금지', array['어떤 차별도 허용 안 함', '국가 개입이 전제됨', '침해 구제를 요구함'], '{}'::text[], '평등권은 합당한 근거 없이 불평등한 대우를 받지 않을 권리다. 합리적인 근거가 있는 차등까지 모두 금지하는 것은 아니다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 8),
  ('social-jo-010', 'social-jo', 'choice', '기본권의 종류', null, '투표권·피선거권·국민 투표권이 속하는 기본권 X. X의 의미는?', null, '국가 의사 결정 참여', array['인간다운 생활 요구', '국가 간섭 배제', '침해된 권리 구제'], '{}'::text[], '투표권, 피선거권, 국민 투표권은 참정권이다. 참정권은 국가의 의사 결정에 참여할 수 있는 권리다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 9),
  ('social-jo-011', 'social-jo', 'choice', '기본권의 종류', null, '참정권에 대한 설명으로 옳지 않은 것은?', null, '외국인에게 원칙적 인정', array['국가 의사 결정에 참여', '피선거권 포함', '국민 투표권 포함'], '{}'::text[], '참정권은 국가의 의사 결정에 참여할 수 있는 권리로 투표권·피선거권·국민 투표권 등이 있으며, 원칙적으로 외국인에게는 인정되지 않는다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 10),
  ('social-jo-012', 'social-jo', 'choice', '기본권의 종류', null, '노동자들이 선거권을 요구한 차티스트 운동과 관련 깊은 기본권은?', null, '참정권', array['사회권', '청구권', '자유권'], '{}'::text[], '차티스트 운동은 노동자들이 선거권 확대를 요구한 운동으로, 국가의 의사 결정에 참여할 권리인 참정권과 관련 깊다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 11),
  ('social-jo-013', 'social-jo', 'choice', '기본권의 종류', null, '국민이 국가에 인간다운 생활의 보장을 요구할 수 있는 권리는?', null, '사회권', array['자유권', '청구권', '참정권'], '{}'::text[], '사회권은 국민이 국가에 인간다운 생활의 보장을 적극적으로 요구할 수 있는 권리다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 12),
  ('social-jo-014', 'social-jo', 'choice', '기본권의 종류', null, '다른 기본권이 침해되었을 때 구제를 요구할 수 있는 수단적 권리는?', null, '청구권', array['사회권', '참정권', '평등권'], '{}'::text[], '청구권은 다른 기본권이 침해되었을 때 이의 구제를 요구할 수 있는 권리로, 기본권을 지키기 위한 수단적 성격의 기본권이다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 13),
  ('social-jo-015', 'social-jo', 'choice', '기본권의 종류', null, '국가의 개입이 전제되어야 보장되는 기본권 A, B. A–B는?', null, '사회권–청구권', array['자유권–평등권', '자유권–참정권', '평등권–청구권'], '{}'::text[], '사회권은 국가에 인간다운 생활 보장을, 청구권은 침해된 기본권의 구제를 요구하는 권리로 둘 다 국가의 개입이 전제되어야 보장된다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 14),
  ('social-jo-016', 'social-jo', 'choice', '기본권의 종류', null, '국가에 대한 소극적 권리 A, 국가에 적극적으로 요구하는 권리 B. A–B는?', null, '자유권–사회권', array['사회권–자유권', '청구권–자유권', '참정권–평등권'], '{}'::text[], '자유권은 국가의 간섭을 막는 소극적 권리이고, 사회권은 국가에 인간다운 생활의 보장을 적극적으로 요구하는 권리다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 15),
  ('social-jo-017', 'social-jo', 'choice', '기본권의 종류', null, '인간의 존엄과 인간 존중을 위한 본질적 권리로 묶이는 A, B. A–B는?', null, '자유권–평등권', array['사회권–청구권', '참정권–청구권', '사회권–참정권'], '{}'::text[], '자유권과 평등권은 인간의 존엄과 인간 존중을 위한 본질적 권리로 정리된다. 사회권·청구권은 국가의 개입이 전제되는 권리다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 16),
  ('social-jo-018', 'social-jo', 'choice', '기본권의 제한', null, '헌법 제37조 ②가 기본권 제한의 목적으로 들지 않은 것은?', null, '국가 경제 성장', array['국가 안전 보장', '질서 유지', '공공복리'], '{}'::text[], '헌법 제37조 ②는 국가 안전 보장, 질서 유지 또는 공공복리를 위하여 필요한 경우에 한하여 기본권을 제한할 수 있다고 정한다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 17),
  ('social-jo-019', 'social-jo', 'choice', '기본권의 제한', null, '헌법 제37조 ②에 따르면 기본권은 무엇으로써 제한할 수 있는가?', null, '법률', array['명령', '조례', '대통령의 결정'], '{}'::text[], '국민의 모든 자유와 권리는 필요한 경우에 한하여 국회가 만든 법률로써 제한할 수 있다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 18),
  ('social-jo-020', 'social-jo', 'choice', '기본권의 제한', null, '기본권을 법률로 제한하는 경우에도 침해할 수 없는 것은?', null, '자유와 권리의 본질적 내용', array['국회가 정한 제한 범위', '공무원의 직무상 재량', '공공복리 실현 요구'], '{}'::text[], '헌법 제37조 ②에 따라 기본권을 제한하는 경우에도 자유와 권리의 본질적인 내용을 침해할 수 없다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 19),
  ('social-jo-021', 'social-jo', 'choice', '기본권의 제한', null, '기본권 제한의 한계에 대한 설명으로 옳지 않은 것은?', null, '사익이 더 커도 제한 가능', array['필요한 범위 안에서만', '정당한 목적이 있어야 함', '본질적 내용 침해 불가'], '{}'::text[], '기본권은 정당한 목적을 달성하는 데 필요한 범위 안에서만 제한해야 하며, 보호하려는 공익이 침해되는 개인의 이익보다 커야 한다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 20),
  ('social-jo-022', 'social-jo', 'choice', '기본권의 제한', null, '법률은 국회, 명령은 행정부가 만든다. 조례 A, 규칙 B를 만드는 곳은?', null, '지방 의회–자치 단체장', array['자치 단체장–지방 의회', '국회–지방 의회', '행정부–국회'], '{}'::text[], '법률은 국회, 명령은 행정부가 만드는 중앙 차원의 법이고, 조례는 지방 의회, 규칙은 지방 자치 단체장(지방 행정부)이 만드는 지방 차원의 법이다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 21),
  ('social-jo-023', 'social-jo', 'choice', '권력 분립', null, '국가 권력을 나누어 각 기관이 서로 견제와 균형을 이루게 하는 제도는?', null, '권력 분립 제도', array['복수 정당 제도', '선거 공영제', '헌법 소원 제도'], '{}'::text[], '권력 분립 제도는 국가 권력을 나누어 각각 다른 기관에 분담시켜 상호 견제와 균형을 이루도록 하는 제도다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 22),
