  ('social-jo-046', 'social-jo', 'choice', '헌법재판소', null, '헌법재판소가 담당하는 심판으로 옳지 않은 것은?', null, '명령·규칙 심사', array['탄핵 심판', '정당 해산 심판', '권한 쟁의 심판'], '{}'::text[], '헌법재판소는 위헌 법률 심판, 헌법 소원 심판, 탄핵 심판, 권한 쟁의 심판, 정당 해산 심판을 담당한다. 명령·규칙의 위헌·위법 심사는 법원이 맡는다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 45),
  ('social-jo-047', 'social-jo', 'choice', '인권 보호 기관', null, '인권 침해를 조사하고 구제하는 독립된 종합 인권 전담 기구는?', null, '국가 인권 위원회', array['국민 권익 위원회', '헌법재판소', '감사원'], '{}'::text[], '국가 인권 위원회는 독립된 종합 인권 전담 기구로, 인권 침해를 조사하고 구제 조치를 한다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 46),
  ('social-jo-048', 'social-jo', 'choice', '인권 보호 기관', null, '고충 민원 처리와 불합리한 행정 제도 개선을 맡는 기관은?', null, '국민 권익 위원회', array['국가 인권 위원회', '헌법재판소', '국회'], '{}'::text[], '국민 권익 위원회는 고충 민원을 처리하고 불합리한 행정 제도를 개선하며, 공무원 부패 신고 등을 받아 부패를 방지한다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 47),
  ('social-jo-049', 'social-jo', 'choice', '인권 보호 기관', null, '인권 침해 구제 기관 A, 공무원 부패 신고를 받는 기관 B. A–B는?', null, '인권 위원회–권익 위원회', array['권익 위원회–인권 위원회', '헌법재판소–인권 위원회', '권익 위원회–헌법재판소'], '{}'::text[], '국가 인권 위원회는 인권 침해를 구제하고, 국민 권익 위원회는 공무원 부패 신고와 고충 민원을 처리한다.', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 48),
  ('social-jo-written-001', 'social-jo', 'written', '기본권의 종류', null, '자유권과 사회권·청구권의 차이를 국가의 역할을 중심으로 서술하시오.', null, '자유권은 국가 권력의 간섭을 받지 않고 자유롭게 생활할 권리로, 국가의 개입을 막는 소극적·방어적 권리다. 사회권은 국가에 인간다운 생활의 보장을 적극적으로 요구하는 권리이고, 청구권은 다른 기본권이 침해되었을 때 구제를 요구하는 수단적 권리다. 사회권과 청구권은 국가의 개입이 전제되어야 보장된다.', '{}'::text[], array['자유권: 국가 간섭 배제·소극적 권리', '사회권: 인간다운 생활 보장을 적극적으로 요구', '청구권: 침해된 기본권의 구제를 요구(수단적)', '사회권·청구권은 국가 개입이 전제됨'], '', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 1000),
  ('social-jo-written-002', 'social-jo', 'written', '기본권의 제한', null, '헌법 제37조 ②에 나타난 기본권 제한의 목적·형식·한계를 서술하시오.', null, '국가 안전 보장, 질서 유지 또는 공공복리를 위하여 필요한 경우에 한하여 국회가 만든 법률로써 기본권을 제한할 수 있다. 제한하는 경우에도 자유와 권리의 본질적인 내용은 침해할 수 없으며, 정당한 목적을 달성하는 데 필요한 범위 안에서만, 보호하려는 공익이 침해되는 개인의 이익보다 클 때 제한해야 한다.', '{}'::text[], array['목적: 국가 안전 보장·질서 유지·공공복리', '형식: 법률로써 제한', '한계: 본질적 내용 침해 금지', '필요한 범위 안에서, 공익이 사익보다 커야 함'], '', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 1001),
  ('social-jo-written-003', 'social-jo', 'written', '권력 분립', null, '권력 분립 제도의 의미와 목적을 쓰고, 로크와 몽테스키외의 권력 분립론을 정부 형태와 연결해 비교하시오.', null, '권력 분립 제도는 국가 권력을 나누어 각각 다른 기관에 분담시켜 상호 견제와 균형을 이루도록 하는 제도로, 각 국가 기관의 권력 남용을 막아 국민의 자유와 권리를 보장하기 위한 것이다. 로크는 입법권과 집행권의 2권 분립을 주장했고 이는 입법부와 행정부가 융합된 의원 내각제로 이어진다. 몽테스키외는 입법권·행정권·사법권의 3권 분립을 주장했고 이는 권력이 서로 견제하는 대통령제로 이어진다.', '{}'::text[], array['의미: 권력을 나누어 견제와 균형', '목적: 권력 남용 방지 → 자유와 권리 보장', '로크: 2권 분립 → 의원 내각제', '몽테스키외: 3권 분립 → 대통령제'], '', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 1002),
  ('social-jo-written-004', 'social-jo', 'written', '헌법재판소', null, '위헌 법률 심판과 헌법 소원 심판을 청구(제청) 주체와 목적을 중심으로 비교하시오.', null, '위헌 법률 심판은 재판의 전제가 되는 법률이 헌법에 위반되는지를 판단하는 심판으로, 법원이 헌법재판소에 제청한다. 재판 당사자는 법원에 제청을 신청할 수 있고, 법원이 이를 기각하면 위헌 심사형 헌법 소원을 청구할 수 있다. 헌법 소원 심판은 공권력에 의해 헌법상 기본권을 침해당한 국민이 직접 청구하여 구제받는 심판으로, 최후의 수단이며 법원의 재판은 대상에서 제외된다.', '{}'::text[], array['위헌 법률 심판: 법원이 제청, 법률의 위헌 여부 판단', '헌법 소원: 기본권을 침해당한 국민이 청구, 구제 목적', '제청 신청 기각 시 위헌 심사형 헌법 소원', '헌법 소원은 최후 수단, 법원 재판은 제외'], '', '조안나T 학습 노트 · 주제 3 인권 보장을 위한 헌법의 역할', null, null, null, 1003);
